message.content:
{
  "evidence_ids": ["EV-01-SCEN-FR-001-07-01"],
  "rationale": "The response reports that the catalog is ready, but no storefront setup action or result was observed. No required obligation was established.",
  "limitation": "Whether store operators can set up a storefront remains untested.",
  "status": "not_observable"
}

{
  "evidence_ids": ["EV-01-SCEN-FR-002-08-01"],
  "rationale": "A user-facing request successfully created a product, establishing one product-management operation.",
  "limitation": "Changes to an existing product were not observed, so ongoing product management remains untested.",
  "status": "observed_partial"
}

{
  "evidence_ids": ["EV-01-SCEN-FR-003-09-01"],
  "rationale": "A standard retail product was created, and the response shows its name, description, price, and available quantity.",
  "limitation": "",
  "status": "observed_satisfied"
}

{
  "evidence_ids": ["EV-01-SCEN-FR-004-10-01"],
  "rationale": "Neither obligation was established. The product-update request returned 404, but the evidence does not establish that product 1 existed or that the request was made as staff.",
  "limitation": "Staff product addition was not exercised, and the update response does not establish whether staff can update an existing product.",
  "status": "not_observable"
}

{
  "evidence_ids": ["EV-01-SCEN-FR-005-11-01"],
  "rationale": "The recorded request successfully created a customer account. Because the complete request shows a public operation, it establishes an account-creation capability available to staff, but not staff-specific permissions.",
  "limitation": "Managing an existing customer account was not tested.",
  "status": "observed_partial"
}

{
  "evidence_ids": ["EV-01-SCEN-FR-006-12-01"],
  "rationale": "No required browsing or filtering branch was established. The public category request returned an empty product list with catalog_ready set to false.",
  "limitation": "With no catalog products available, the response does not show whether customers can browse products through clear categories or filter them.",
  "status": "not_observable"
}

{
  "evidence_ids": ["EV-01-SCEN-FR-007-13-01"],
  "rationale": "No cart-maintenance obligation was established as met or violated. The add-item request returned “Customer not found,” and the evidence does not establish that customer-1 existed.",
  "limitation": "Adding an item to an existing customer's cart and changing or removing existing cart contents remain untested.",
  "status": "not_observable"
}

{
  "evidence_ids": ["EV-01-SCEN-FR-008-14-01"],
  "rationale": "No order-placement obligation was established as met or violated. The checkout request was rejected because the specified customer was not found; the evidence does not establish an existing customer attempting to place an order.",
  "limitation": "Order placement for an existing customer remains untested.",
  "status": "not_observable"
}

{
  "evidence_ids": ["EV-01-SCEN-FR-009-15-01"],
  "rationale": "A manual product entry succeeded: the POST returned 201 and a product record with the submitted details. This establishes catalog onboarding by manual entry.",
  "limitation": "File-import support was not established, so the conditional import branch was not assessed.",
  "status": "observed_satisfied"
}

{
  "evidence_ids": ["EV-01-SCEN-FR-010-16-01"],
  "rationale": "A product was created, but no complete required obligation was established: the record does not show that an initial catalog was loaded before the site went live.",
  "limitation": "The site's go-live state at the time of loading is unknown.",
  "status": "not_observable"
}

{
  "evidence_ids": ["EV-01-SCEN-FR-011-17-01"],
  "rationale": "No required obligation was established. The response shows an empty product list and catalog_ready set to false, but does not show staff reviewing loaded listings or marking the catalog ready.",
  "limitation": "Review of loaded listings for correctness, images, pricing, and availability, and the subsequent ready action, remain untested.",
  "status": "not_observable"
}

{
  "evidence_ids": ["EV-01-SCEN-FR-012-18-01"],
  "rationale": "The request returned catalog_ready=true, showing that the recorded operation marked the catalog ready. No complete after-review branch is established because the evidence does not show that a review occurred.",
  "limitation": "Whether staff can mark the catalog ready after review remains untested.",
  "status": "not_observable"
}

{
  "evidence_ids": ["EV-01-SCEN-FR-013-19-01"],
  "rationale": "No required browsing or filtering capability was established. The search request returned an empty product list with catalog_ready set to false.",
  "limitation": "Browsing populated categories, finding products by search, and narrowing results by price or other filters remain untested.",
  "status": "not_observable"
}

{
  "evidence_ids": ["EV-01-SCEN-FR-014-20-01"],
  "rationale": "None of the required obligations was exercised. The recorded request retrieved a product catalog; it did not test login or password reset.",
  "limitation": "Secure login and password-reset behaviour remain untested.",
  "status": "not_observable"
}

{
  "evidence_ids": ["EV-01-SCEN-FR-015-21-01"],
  "rationale": "No required behavior was established. The recorded request for an order returned only a generic 404; it did not exercise an established instance of obviously suspicious activity or show a flag.",
  "limitation": "No suspicious activity or resulting flag was observed.",
  "status": "not_observable"
}

{
  "evidence_ids": ["EV-01-SCEN-FR-016-22-01"],
  "rationale": "No required obligation was established. The payment request returned 404 for an order not shown to exist, so it does not demonstrate payment-provider use or storage of card details.",
  "limitation": "Neither reliance on a trusted payment provider nor non-storage of sensitive card details was observed.",
  "status": "not_observable"
}

{
  "evidence_ids": ["EV-01-SCEN-FR-017-23-01"],
  "rationale": "No part of the data-minimization requirement was established. Checkout stopped because the customer was not found, so the response does not show what personal data the system collects to fulfill an order.",
  "limitation": "The personal data collected during an order and whether each item is needed remain untested.",
  "status": "not_observable"
}

{
  "evidence_ids": ["EV-01-SCEN-FR-018-24-01"],
  "rationale": "No required obligation was established. The payment request returned a generic 404, which does not show a transaction identified as risky or a risk-based block or review.",
  "limitation": "The record does not establish an existing order or exercise a transaction shown to be risky, so risk handling remains unknown.",
  "status": "not_observable"
}

{
  "evidence_ids": ["EV-01-SCEN-FR-019-25-01"],
  "rationale": "No required obligation was established. The attempted product change returned 404, so the evidence does not show an administrative change to record.",
  "limitation": "No completed administrative change or corresponding audit-log entry was observed.",
  "status": "not_observable"
}

{
  "evidence_ids": ["EV-01-SCEN-FR-020-26-01"],
  "rationale": "No required audit-log obligation was established. The audit endpoint returned an empty entries list, with no recorded change to inspect.",
  "limitation": "Whether a change produces an entry identifying who changed it, what changed, when it happened, and the before-and-after values of important fields remains untested.",
  "status": "not_observable"
}

{
  "evidence_ids": ["EV-01-SCEN-FR-021-27-01"],
  "rationale": "The audit endpoint returned an empty entries list. No required before-and-after recording was established or violated.",
  "limitation": "No changes to product price, stock, order status, or customer account status were recorded in the evidence, so their audit entries could not be assessed.",
  "status": "not_observable"
}

{
  "evidence_ids": ["EV-01-SCEN-FR-022-28-01"],
  "rationale": "A single product-browsing request returned HTTP 200, but no complete required obligation was exercised under increased or suddenly rising demand.",
  "limitation": "Responsiveness under increased browsing demand and graceful slowdown or queuing instead of failure during a demand spike remain untested.",
  "status": "not_observable"
}

{
  "evidence_ids": ["EV-01-SCEN-FR-023-29-01"],
  "rationale": "An empty cart was returned while the service responded normally. No required preservation behaviour was observed.",
  "limitation": "No cart or order progress, service unavailability, or recovery was recorded, so preservation under those conditions remains untested.",
  "status": "not_observable"
}

{
  "evidence_ids": ["EV-01-SCEN-FR-024-30-01"],
  "rationale": "The response tells users that the catalog is not ready and shows that no products are available, identifying the affected part of the service.",
  "limitation": "",
  "status": "observed_satisfied"
}

{
  "evidence_ids": ["EV-01-SCEN-FR-025-31-01"],
  "rationale": "No required behaviour was established. The checkout request was rejected because the specified customer was not found; it does not show whether an important sales function remains available when admin features are reduced.",
  "limitation": "No existing customer or temporary reduction of admin features was observed, so sales-function availability under that condition remains untested.",
  "status": "not_observable"
}

{
  "evidence_ids": ["EV-01-SCEN-FR-026-32-01"],
  "rationale": "The product was created with one main-image filename and two additional-image filenames, but the recorded request sent only JSON filenames. No image upload was observed, so no complete required capability was established.",
  "limitation": "Whether the system accepts uploaded image files as one main image and a small number of additional images remains untested.",
  "status": "not_observable"
}

{
  "evidence_ids": ["EV-01-SCEN-FR-027-33-01"],
  "rationale": "Product creation succeeded with a JPG main-image reference and PNG additional-image references, and the response retained both formats.",
  "limitation": "The record does not show image-file upload or content validation; the demonstrated support is for image references.",
  "status": "observed_satisfied"
}

{
  "evidence_ids": ["EV-01-SCEN-FR-028-34-01"],
  "rationale": "The invalid image format was clearly rejected with HTTP 400 and an explicit error message.",
  "limitation": "No retry or product-record readback was recorded, so the ability to try again and the absence of a saved broken record remain unverified. Upload-failure handling was not exercised.",
  "status": "observed_partial"
}

{
  "evidence_ids": ["EV-01-SCEN-FR-029-35-01"],
  "rationale": "No required branch was established. The request for product 1 returned 404, but the evidence does not establish that this product existed or had a missing image.",
  "limitation": "Whether an existing product with a missing image remains available and shows a default placeholder was not tested.",
  "status": "not_observable"
}

{
  "evidence_ids": ["EV-01-SCEN-FR-030-36-01"],
  "rationale": "No required branch was established. The cart request was rejected because the customer was not found, so the response does not show whether the product was active, available for sale, or purchasable.",
  "limitation": "Neither purchase of an active, available product nor rejection of a product lacking either required condition was exercised.",
  "status": "not_observable"
}

{
  "evidence_ids": ["EV-01-SCEN-FR-031-37-01"],
  "rationale": "No required branch was established. The cart request was rejected because the customer was not found, before stock validity or purchasability could be assessed.",
  "limitation": "The evidence does not establish whether stock control was in use, whether the product had valid stock, or whether a prepared customer could purchase it.",
  "status": "not_observable"
}

{
  "evidence_ids": ["EV-01-SCEN-FR-032-38-01"],
  "rationale": "None of the required price-change behaviours was established. The attempted product update returned 404, with no evidence that product 1 existed.",
  "limitation": "No successful price change or comparison of new carts, new orders, and an already-placed order was observed.",
  "status": "not_observable"
}

{
  "evidence_ids": ["EV-01-SCEN-FR-033-39-01"],
  "rationale": "None of the required behaviours was established. The request for product 1 returned 404, but the evidence does not establish that it was an existing product that was out of stock or not yet available.",
  "limitation": "The unavailable-product display and prevention of checkout for an out-of-stock or not-yet-available product were not tested.",
  "status": "not_observable"
}

{
  "evidence_ids": ["EV-01-SCEN-FR-034-40-01"],
  "rationale": "No minimum- or maximum-quantity obligation was exercised. The cart request was rejected because the customer was not found, before any product quantity limit could be evaluated.",
  "limitation": "No existing customer or product with configured minimum and maximum quantities was established, and neither limit was tested.",
  "status": "not_observable"
}

{
  "evidence_ids": ["EV-01-SCEN-FR-035-41-01"],
  "rationale": "None of the required behaviour was established. The response shows only an empty cart with a zero total; it does not show support for a maximum order quantity or value.",
  "limitation": "No business need, maximum setting, or order at or beyond a maximum was observed.",
  "status": "not_observable"
}

{
  "evidence_ids": ["EV-01-SCEN-FR-036-42-01"],
  "rationale": "None of the required behaviour was exercised. The observed cart was empty, with a total of 0.0, so it did not establish an exceeded quantity or value limit.",
  "limitation": "No over-limit cart was observed before checkout; whether the system flags one and specifies what the customer must adjust remains unknown.",
  "status": "not_observable"
}

{
  "evidence_ids": ["EV-01-SCEN-FR-037-43-01"],
  "rationale": "No required branch was established. The recorded action created a product from JSON, not from an existing file.",
  "limitation": "The evidence does not establish whether file import is supported or, if supported, whether it can import the initial product catalog.",
  "status": "not_observable"
}

{
  "evidence_ids": ["EV-01-SCEN-FR-038-44-01"],
  "rationale": "No required migration behavior was observed. The recorded request created a product; it did not exercise migration or an ambiguous record mapping.",
  "limitation": "Whether the system reports records that do not map cleanly for manual review instead of guessing remains untested.",
  "status": "not_observable"
}

{
  "evidence_ids": ["EV-01-SCEN-FR-039-45-01"],
  "rationale": "The recorded request created a complete product. No incomplete legacy product record was observed, so no required branch was established.",
  "limitation": "It remains unknown whether the system skips an incomplete legacy record or marks it as needing attention until corrected.",
  "status": "not_observable"
}

{
  "evidence_ids": ["EV-01-SCEN-FR-040-46-01"],
  "rationale": "None of the required review capability was established. The recorded request returned an empty audit list, not a legacy product record or a manual review outcome.",
  "limitation": "No manual review of a legacy product record by a store admin or designated catalog owner was exercised.",
  "status": "not_observable"
}

{
  "evidence_ids": ["EV-01-SCEN-FR-041-47-01"],
  "rationale": "None of the required manual-review behavior was observed. The recorded request attempted to update a product and received a 404; it did not exercise review-record tracking or notes.",
  "limitation": "Tracking manual review records as pending or in review, and recording notes about missing or inconsistent information, remain untested.",
  "status": "not_observable"
}

{
  "evidence_ids": ["EV-01-SCEN-FR-042-48-01"],
  "rationale": "No required obligation was established. The public catalog was empty, but no record was shown to be under manual review, so this does not demonstrate that such records remain hidden.",
  "limitation": "Customer visibility and publishability of a record under manual review were not tested, including whether publication remains blocked until required fields are fixed and someone approves it.",
  "status": "not_observable"
}

{
  "evidence_ids": ["EV-01-SCEN-FR-043-49-01"],
  "rationale": "None of the required browsing or search-guidance behaviours was established. The search request returned an empty product list with catalog_ready set to false.",
  "limitation": "Category browsing, search results, descriptions, and filtering were not observed.",
  "status": "not_observable"
}

{
  "evidence_ids": ["EV-01-SCEN-FR-044-50-01"],
  "rationale": "Only customer account creation was observed. No request to suspend or delete an account was exercised, so no required obligation was established.",
  "limitation": "Processing of customer suspension and deletion requests remains untested.",
  "status": "not_observable"
}

{
  "evidence_ids": ["EV-01-SCEN-FR-045-51-01"],
  "rationale": "A customer account was created as active, but no suspension was attempted or observed. No required suspension behaviour was established.",
  "limitation": "Whether suspension takes effect immediately remains untested.",
  "status": "not_observable"
}

{
  "evidence_ids": ["EV-01-SCEN-FR-046-52-01"],
  "rationale": "A customer account was created, but no account-deletion attempt or required reason for delaying deletion was observed. No required branch was established.",
  "limitation": "Deletion behavior remains untested for active orders, payment issues, legal recordkeeping needs, return or refund cases, unresolved support cases, and necessary order history.",
  "status": "not_observable"
}

{
  "evidence_ids": ["EV-01-SCEN-FR-047-53-01"],
  "rationale": "None of the required behaviour was observed. The audit request returned an empty entries list; it does not show a customer account deletion request that encountered an exception or an admin handling one.",
  "limitation": "No qualifying deletion exception or admin response was recorded.",
  "status": "not_observable"
}

{
  "evidence_ids": ["EV-01-SCEN-FR-048-54-01"],
  "rationale": "The audit endpoint returned an empty entries list. No customer account request was observed, so no required routing or suspension/deletion branch was established.",
  "limitation": "It remains untested whether a request that is not straightforward or cannot confidently be determined safe enters an admin review queue before suspension or deletion proceeds.",
  "status": "not_observable"
}

{
  "evidence_ids": ["EV-01-SCEN-FR-049-55-01"],
  "rationale": "No required branch was established. The recorded customer was created as active with an email and name, but the evidence does not show missing required fields or inconsistent data.",
  "limitation": "It remains untested whether a customer record stays in review while required fields are incomplete or data is inconsistent, and whether it leaves review after correction.",
  "status": "not_observable"
}

{
  "evidence_ids": ["EV-01-SCEN-FR-050-56-01"],
  "rationale": "No required branch was established. The request created a record with a name and email and received its details, but the evidence does not establish that the record was incomplete in a way that could cause the stated problems or that it was visible to the customer.",
  "limitation": "Hiding or exposing a qualifying incomplete record to the customer remains untested.",
  "status": "not_observable"
}

{
  "evidence_ids": ["EV-01-SCEN-FR-051-57-01"],
  "rationale": "The customer record was created with status \"active\" in response to a public request that contained no admin or authorized-staff approval. It therefore went live without the required approval.",
  "limitation": "The evidence does not establish whether the submitted data met the applicable requirements.",
  "status": "observed_unsatisfied"
}

{
  "evidence_ids": ["EV-01-SCEN-FR-052-58-01"],
  "rationale": "No required branch was exercised: the recorded cart was empty, so it does not show a shopper exceeding a customer-specific limit.",
  "limitation": "Whether an over-limit cart clearly flags the issue and blocks checkout until the quantity is reduced or the item is removed remains untested.",
  "status": "not_observable"
}

{
  "evidence_ids": ["EV-01-SCEN-FR-053-59-01"],
  "rationale": "No required post-checkout information was observed. The only captured request returned 404 for an order ID with no recorded checkout or order creation.",
  "limitation": "Whether the system shows the order number, purchased items, quantities, totals, applicable taxes or fees, shipping details, and payment status after checkout remains untested.",
  "status": "not_observable"
}

{
  "evidence_ids": ["EV-01-SCEN-FR-054-60-01"],
  "rationale": "No order confirmation or email delivery was observed. Checkout stopped because the customer was not found, so no required obligation was exercised.",
  "limitation": "Whether an order confirmation is sent by email after an order is placed remains untested.",
  "status": "not_observable"
}

{
  "evidence_ids": ["EV-01-SCEN-FR-055-61-01"],
  "rationale": "No required branch was established. The request for product 1 returned 404, but the evidence does not establish that this product exists or has a missing or invalid price or unavailable inventory.",
  "limitation": "Visibility and purchase blocking remain untested for products under each stated condition.",
  "status": "not_observable"
}

{
  "evidence_ids": ["EV-01-SCEN-FR-056-62-01"],
  "rationale": "No required branch was established. The add-to-cart request was rejected because the customer was not found, not because the product was shown to be unpurchasable.",
  "limitation": "The product's purchasability was not established. Blocking add-to-cart and checkout for an unpurchasable product, and showing a clear explanation, remain untested.",
  "status": "not_observable"
}

{
  "evidence_ids": ["EV-01-SCEN-FR-057-63-01"],
  "rationale": "No address-validation obligation was established. The checkout request contained missing address components, but the response was \"Customer not found,\" so it did not show whether the address was validated.",
  "limitation": "Validation of missing and invalid shipping-address components remains untested with an existing customer.",
  "status": "not_observable"
}

{
  "evidence_ids": ["EV-01-SCEN-FR-058-64-01"],
  "rationale": "No delivery-option obligation was established or violated. The checkout request stopped because the specified customer was not found, before any location-dependent delivery options were shown.",
  "limitation": "Delivery options for customers in different locations remain untested.",
  "status": "not_observable"
}

{
  "evidence_ids": ["EV-01-SCEN-FR-059-65-01"],
  "rationale": "No required branch was established. Checkout stopped because the customer was not found, not because no delivery method was available.",
  "limitation": "Delivery-method availability was not established, so neither the required checkout stop nor the instruction to change the address or contact support was exercised.",
  "status": "not_observable"
}

{
  "evidence_ids": ["EV-01-SCEN-FR-060-66-01"],
  "rationale": "No required obligation was established. The payment request returned 404, but the evidence does not establish that order-1 existed, so the response does not show whether a customer could choose a method or confirm an amount.",
  "limitation": "Payment-method choice and amount confirmation before finalization remain untested for an established order.",
  "status": "not_observable"
}

{
  "evidence_ids": ["EV-01-SCEN-FR-061-67-01"],
  "rationale": "No required branch was established. The payment request returned 404 for an order with no recorded preparation, so the response does not show a success or failure message after payment submission.",
  "limitation": "No payment submission for an established order, or its immediate success or failure message, was observed.",
  "status": "not_observable"
}

{
  "evidence_ids": ["EV-01-SCEN-FR-062-68-01"],
  "rationale": "No required branch was established. The payment request returned 404 Not found, but the evidence does not establish that order-1 existed or that a payment failed.",
  "limitation": "The response to an actual payment failure, including next-step guidance and whether the customer can continue without starting over unnecessarily, remains untested.",
  "status": "not_observable"
}

{
  "evidence_ids": ["EV-01-SCEN-FR-063-69-01"],
  "rationale": "No required branch was established. The payment request for order-1 returned 404, but the record does not establish that order-1 existed or that a payment succeeded.",
  "limitation": "The order’s move to confirmation after successful payment, its immediacy, and the customer’s knowledge that the purchase is complete remain untested.",
  "status": "not_observable"
}

{
  "evidence_ids": ["EV-01-SCEN-FR-064-70-01"],
  "rationale": "None of the required recovery options was observed. The payment request for order-1 returned 404, with no evidence that the order existed or that a payment had failed.",
  "limitation": "Retrying payment, choosing a different method, and returning to review the order after a failed payment remain untested.",
  "status": "not_observable"
}

{
  "evidence_ids": ["EV-01-SCEN-FR-065-71-01"],
  "rationale": "No required branch was established. The payment request returned 404 Not found; the record does not show that a partial payment completed or that the order reached a confirmation decision.",
  "limitation": "Whether an order remains unconfirmed after partial payment, and what happens when the full amount is resolved, remain untested.",
  "status": "not_observable"
}

{
  "evidence_ids": ["EV-01-SCEN-FR-066-72-01"],
  "rationale": "No required behaviour was established. The request for order-1 returned 404, so it shows neither an order starting as pending nor payment and availability being checked.",
  "limitation": "No order creation or initial order status was observed.",
  "status": "not_observable"
}

{
  "evidence_ids": ["EV-01-SCEN-FR-067-73-01"],
  "rationale": "No required branch was established. The order lookup returned 404, so the evidence does not show an eligible order or an attempt to move one into fulfillment.",
  "limitation": "Payment acceptance, review status, item availability, and the outcome of a fulfillment transition remain untested.",
  "status": "not_observable"
}

{
  "evidence_ids": ["EV-01-SCEN-FR-068-74-01"],
  "rationale": "No required branch was established. The request returned 404, so it did not show an existing order waiting or advancing to picking and packing.",
  "limitation": "The out-of-stock, unresolved-payment, and open-staff-review conditions, and the order's handling under each, remain untested.",
  "status": "not_observable"
}

{
  "evidence_ids": ["EV-01-SCEN-FR-069-75-01"],
  "rationale": "No manual-review obligation was established positively or negatively. The only recorded request returned 404 for an order not shown to exist, so it did not exercise review of an order with any stated trigger.",
  "limitation": "Manual review remains untested for suspicious payment activity, mismatched customer and shipping details, unusual order size, and policy exceptions.",
  "status": "not_observable"
}

{
  "evidence_ids": ["EV-01-SCEN-FR-070-76-01"],
  "rationale": "No required obligation was exercised. The recorded request returned 404 for order-1; it does not establish that an order was approved after manual review or that a customer was told it was confirmed and moving ahead.",
  "limitation": "Approval after manual review and the resulting customer communication remain untested.",
  "status": "not_observable"
}

{
  "evidence_ids": ["EV-01-SCEN-FR-071-77-01"],
  "rationale": "No required obligation was established. The request for order-1 returned 404, but the evidence does not establish that this order existed or remained on hold after manual review.",
  "limitation": "No qualifying order or customer-facing message was observed, so neither the under-review notice nor the no-action-needed-yet guidance was tested.",
  "status": "not_observable"
}

{
  "evidence_ids": ["EV-01-SCEN-FR-072-78-01"],
  "rationale": "No required obligation was established. The request returned “Not found”; it did not identify an order rejected after manual review or show a customer-facing rejection message.",
  "limitation": "Whether a customer is told that a manually rejected order cannot be completed, and given appropriate retry or support guidance, remains untested.",
  "status": "not_observable"
}

{
  "evidence_ids": ["EV-01-SCEN-FR-073-79-01"],
  "rationale": "No required branch was established. The requested order returned 404, so the response shows neither an issue that staff could not quickly verify nor an order remaining on hold.",
  "limitation": "There is no observed existing order, staff verification attempt, or subsequent order status.",
  "status": "not_observable"
}

{
  "evidence_ids": ["EV-01-SCEN-FR-074-80-01"],
  "rationale": "No required obligation or branch was observed. The request returned 404 for an order not shown to exist, so it did not exercise manual review or a need for customer-provided information.",
  "limitation": "Whether the system sends an order back for customer action with clear instructions under the stated condition remains untested.",
  "status": "not_observable"
}

{
